/// <summary>
/// PricingAttribute of table <c>CustDirectDebitMandate</c> field CancellationDate.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeCustDirectDebitMandateCancellationDate extends GUPPricingAttributeCustDirectDebitMandate implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustDirectDebitMandate, CancellationDate);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::Date);
    CustDirectDebitMandate custDirectDebitMandate;

    while select custDirectDebitMandate
        group by CancellationDate
    {
        if (! ret.in(custDirectDebitMandate.CancellationDate))
        {
            ret.add(custDirectDebitMandate.CancellationDate);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustDirectDebitMandate, CancellationDate));
    qbr.value(queryValue(_value));
}
